function New-RapMemoryOutputDependencies {$s=[pscustomobject]@{Operations=@{};Specifications=[Collections.Generic.List[object]]::new();Datasets=[Collections.Generic.List[object]]::new();Artifacts=[Collections.Generic.List[object]]::new();Manifests=[Collections.Generic.List[object]]::new();Packages=[Collections.Generic.List[object]]::new();Audits=[Collections.Generic.List[object]]::new()};$d=[pscustomobject]@{GetOperation={param($id)$s.Operations[$id]}.GetNewClosure();CommitGeneration={param($spec,$dataset,$artifact,$manifest,$operation,$audit)$s.Specifications.Add($spec);$s.Datasets.Add($dataset);$s.Artifacts.Add($artifact);$s.Manifests.Add($manifest);$s.Audits.Add($audit);$s.Operations[$operation.OperationId]=$operation}.GetNewClosure();SavePackage={param($package)$s.Packages.Add($package)}.GetNewClosure()};[pscustomobject]@{State=$s;Dependencies=$d}}
